import subprocess, os, math
def blockcomp(path, bs, algo):
    data=open(path,'rb').read()
    tot=0
    for i in range(0,len(data),bs):
        chunk=data[i:i+bs]
        if algo=='xz':
            # squashfs xz: lzma filter, dictionary = block size
            p=subprocess.run(['xz','--format=raw','--lzma1=preset=9e,dict=%d'%bs,'-c'],input=chunk,capture_output=True)
        elif algo=='zstd':
            p=subprocess.run(['zstd','-15','-q','-c'],input=chunk,capture_output=True)
        elif algo=='gzip':
            p=subprocess.run(['gzip','-9','-c'],input=chunk,capture_output=True)
        tot+=len(p.stdout)
    return len(data), tot

